	// If we treat non-zero exit codes of `rpm` as errors,
	// we will be missing a partial package list we can get.

	if !r.isSuccess() && r.Stdout == "" {
		return nil, xerrors.Errorf("Failed to query package ownership: %s", r)
	}
	seen := map[string]struct{}{}
	scanner := bufio.NewScanner(strings.NewReader(r.Stdout))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || rpmOwnershipLineIgnorable(line) { continue }
		pack, err := o.parseInstalledPackagesLine(line)
		if err != nil {
			return nil, xerrors.Errorf("Failed to parse rpm -qf line %q: %w", line, err)
		}
		p, ok := o.Packages[pack.Name]
		if !ok || p.Version != pack.Version || p.Release != pack.Release || (pack.Arch != "" && p.Arch != pack.Arch) {
			continue
		}
		fqpn := p.FQPN()
		if _, ok := seen[fqpn]; !ok { seen[fqpn] = struct{}{}; pkgNameVerRels = append(pkgNameVerRels, fqpn) }
	}
	if err := scanner.Err(); err != nil { return nil, err }
	return pkgNameVerRels, nil
}

